  rights: [R('rm-d006', 'Thirty people were picked up near a stone-throwing. What must happen within 24 hours?', [
    ['a', 'Each person must be told the grounds, allowed a lawyer, and produced before a magistrate; those without individual grounds released.', true, 'Correct. Arrest safeguards apply person by person; a group sweep does not change that.'],
    ['b', 'The group can be held until the investigation finishes, however long that takes.', false, 'Detention beyond 24 hours needs a magistrate’s order, and grounds must be individual.'],
    ['c', 'They can be held as long as no one is physically harmed.', false, 'Liberty is not only about injury; detention itself needs lawful grounds and judicial oversight.'],
  ], 'Article 22 requires that an arrested person be told the grounds, allowed to consult a lawyer, and produced before a magistrate within 24 hours. Article 21 protects liberty from arbitrary detention.', 'Twenty-five of the thirty were wedding guests; only individual evidence could separate them from the five.', SRC.liberty, {
    question: 'Thirty people were picked up near a stone fight. What must happen within 24 hours?',
    options: ['Each must be told why, get a lawyer, and see a judge. Free those with no proof.', 'Hold the group until the case is finished.', 'Hold them as long as nobody is hurt.'],
    feedback: ['Yes! Rights work person by person.', 'No. After 24 hours a judge must decide, person by person.', 'Being locked up is itself a harm. It needs real reasons.'],
    principle: 'Anyone arrested must be told why, may see a lawyer, and must see a judge within 24 hours.',
    why: 'Most of the thirty were wedding guests. Only real proof could tell them apart from the five.',
  })],
